//! Tests a migration on rows: the one engine behind a playground's **Test
//! migration** and the migration oracle (`romulus-migration/tests/oracle`),
//! so the two can never disagree on what "the migration works" means.
//!
//! Given a Postgres [`Session`] holding the base schema, a [`Check`] runs:
//!
//! 1. **seed**: rows generated by romulus-fakedata, provided, or already
//!    there ([`Seed`]);
//! 2. **before**: the database is at the base model exactly; every table
//!    counted, a sample of rows taken by primary key;
//! 3. **up**: each statement in its own transaction, measured (duration,
//!    locks from `pg_locks`, rewrites, rows changed: [`statements`]);
//! 4. **after up**: the schema is the target model exactly; row counts
//!    kept; the sampled rows found again, renamed columns followed, a
//!    converted column holding what the migration's own cast gives, and
//!    what does not convert back named as rounded ([`checks`]);
//! 5. **down** (when there is one), measured the same way;
//! 6. **after down**: the schema is the base model again; the counts and
//!    the sampled rows are back with their original values, and what is not
//!    is data loss, matched against the statement that explains it and its
//!    flag ([`report::DataLoss`]); no sequence went back.
//!
//! The verdict ([`Verdict`]): failed, needing a developer's
//! acknowledgement (data changed that the migration does not declare),
//! passed up only (no down migration), or passed. A run whose touched
//! tables were all empty checked nothing on rows ([`Report::nothing_checked`]).
//!
//! The [`Report`] is serializable as is. What each statement does to the
//! rows is read from its parse tree ([`effects`]), renames included: the
//! check follows exactly what runs.
//!
//! Nothing here knows where it runs: a playground's session cancels a
//! statement past its limit and terminates its backend, a scratch
//! database's (feature `sqlx`) gives up waiting. Postgres 16 or later
//! (romulus-fakedata's load).

pub mod checks;
pub mod compare;
pub mod effects;
pub mod report;
pub mod seed;
pub mod session;
pub mod snapshot;
pub mod statements;

use std::time::Duration;

pub use compare::{SchemaOptions, differences, introspect};
use remus_core::Schema;
pub use report::*;
pub use seed::Seed;
pub use session::{Answer, DbError, Rows, Session, SessionError};
pub use statements::{Limits, Progress, Statement};
use tokio::time::Instant;

use crate::{
    checks::{Context, Located},
    effects::Walk,
    statements::millis,
};

/// Tables listed in a check, at most (the rest are counted in its summary).
pub const MAX_TABLES_LISTED: usize = 200;

/// How a test runs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Options {
    /// Rows sampled per table.
    pub sample: usize,
    /// Each statement (and each of the engine's own queries), at most.
    pub statement_deadline: Duration,
    /// The whole test, at most.
    pub budget: Duration,
    /// The database runs every policy for `PUBLIC` (a playground).
    pub policies_public: bool,
    /// What the report calls the two schemas: `v7`, `the draft`.
    pub base_label: String,
    pub target_label: String,
}

impl Default for Options {
    fn default() -> Self {
        Self {
            sample: 25,
            statement_deadline: Duration::from_mins(2),
            budget: Duration::from_mins(10),
            policies_public: false,
            base_label: "the base schema".to_owned(),
            target_label: "the target schema".to_owned(),
        }
    }
}

/// One direction of a migration.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Migration {
    pub statements: Vec<Statement>,
    /// Tables and composite types (`schema.name`) whose columns it warned
    /// Postgres puts last.
    pub reordered: Vec<String>,
}

impl Migration {
    /// A migration romulus-migration planned.
    pub fn planned(migration: &romulus_migration::Migration) -> Self {
        Self {
            statements: Statement::all_planned(migration),
            reordered: compare::reordered(migration),
        }
    }

    /// A migration written by hand, or why it does not split.
    pub fn written(text: &str) -> Result<Self, String> {
        Ok(Self {
            statements: Statement::split(text)?,
            reordered: Vec::new(),
        })
    }
}

/// A test to run.
#[derive(Debug, Clone)]
pub struct Check {
    /// What the database holds before (its schema).
    pub base: Schema,
    /// What the up migration makes of it.
    pub target: Schema,
    pub up: Migration,
    /// `None`: there is none (a migration written without one).
    pub down: Option<Migration>,
    pub seed: Seed,
    pub options: Options,
}

/// Runs the test on `session` (holding `check.base`'s schema, and its rows
/// for [`Seed::Existing`]), telling `on` as it goes.
#[allow(clippy::too_many_lines, reason = "the phases, in order")]
pub async fn run<S: Session>(
    session: &mut S,
    check: &Check,
    on: &mut (dyn FnMut(Event) + Send),
) -> Report {
    let started = Instant::now();
    let options = &check.options;
    let limits = Limits::new(options.statement_deadline, options.budget);
    let mut run = Run {
        phases: Vec::new(),
        data: report::DataSource::Provided,
        up: MigrationReport::default(),
        down: None,
        down_status: if check.down.is_some() {
            DownStatus::NotRun
        } else {
            DownStatus::NotProvided
        },
        losses: Vec::new(),
        tables: 0,
        rows: 0,
        nothing_checked: false,
        empty_tables: Vec::new(),
        policies_public: options.policies_public,
    };

    // Seed.
    on(Event::Phase { phase: Phase::Seed });
    let at = Instant::now();
    match seed::seed(session, &check.base, &check.seed, limits).await {
        Ok(seeded) => {
            run.data = seeded.data;
            let mut phase = PhaseReport {
                phase: Phase::Seed,
                status: Status::Passed,
                duration_ms: millis(at),
                summary: match &check.seed {
                    Seed::Generate(_) => "Rows generated.".to_owned(),
                    // A phrase saying what the rows are: the step says it.
                    Seed::Existing { label } => {
                        let mut chars = label.chars();
                        chars.next().map_or_else(String::new, |first| {
                            format!("{}{}.", first.to_uppercase(), chars.as_str())
                        })
                    }
                    Seed::Sql(_) => "Rows inserted.".to_owned(),
                },
                checks: Vec::new(),
            };
            if !seeded.notes.is_empty() {
                phase.checks.push(CheckReport {
                    kind: CheckKind::Rows,
                    status: Status::Passed,
                    summary: "What the generator could not satisfy:".to_owned(),
                    details: seeded.notes.into_iter().take(50).collect(),
                    tables: Vec::new(),
                });
            }
            run.push(phase, on);
        }
        Err(message) => {
            run.push(
                PhaseReport {
                    phase: Phase::Seed,
                    status: Status::Failed,
                    duration_ms: millis(at),
                    summary: message.clone(),
                    checks: Vec::new(),
                },
                on,
            );
            return run.finish(
                started,
                check,
                format!("Failed before the migration: {message}"),
            );
        }
    }

    // Before: the base schema, its rows.
    on(Event::Phase {
        phase: Phase::Before,
    });
    let at = Instant::now();
    let base_options = SchemaOptions {
        reordered: Vec::new(),
        policies_public: options.policies_public,
    };
    let schema = checks::check_schema(
        session,
        &check.base,
        &base_options,
        &options.base_label,
        limits,
    )
    .await;
    let tables = snapshot::tables(&check.base);
    let before = if schema.status == Status::Failed {
        None
    } else {
        Some(snapshot::take(session, &tables, options.sample, limits).await)
    };
    let mut phase = PhaseReport {
        phase: Phase::Before,
        status: schema.status,
        duration_ms: 0,
        summary: String::new(),
        checks: vec![schema],
    };
    let before = match before {
        Some(Ok(before)) => {
            run.tables = before.counts.len();
            run.rows = before.rows();
            phase.summary = format!(
                "{} rows in {} tables; {} sampled by primary key.",
                checks::thousands(before.rows()),
                before.counts.len(),
                checks::thousands(i64::try_from(before.sampled()).unwrap_or(0))
            );
            phase.duration_ms = millis(at);
            run.push(phase, on);
            before
        }
        Some(Err(err)) => {
            phase.status = Status::Failed;
            phase.summary = format!("The rows could not be read: {err}");
            phase.duration_ms = millis(at);
            let message = phase.summary.clone();
            run.push(phase, on);
            return run.finish(
                started,
                check,
                format!("Failed before the migration: {message}"),
            );
        }
        None => {
            phase.summary = format!("The database is not at {}.", options.base_label);
            phase.duration_ms = millis(at);
            let message = phase.summary.clone();
            run.push(phase, on);
            return run.finish(
                started,
                check,
                format!("Failed before the migration: {message}"),
            );
        }
    };

    // Up.
    let (up_walk, up_effects) = effects::walk(
        Walk::new(&check.base),
        check.up.statements.iter().map(|s| s.sql.as_str()),
    );
    let mut located = Located::all(Direction::Up, &check.up.statements, up_effects);
    let coverage = coverage(&tables, &before, &up_walk, &located);
    run.nothing_checked = coverage.nothing_checked;
    run.empty_tables.clone_from(&coverage.empty);
    on(Event::Phase { phase: Phase::Up });
    run.up = statements::run(session, &check.up.statements, limits, &mut |p| {
        on(progress(Direction::Up, p));
    })
    .await;
    let up_failed = run.up.failed_at;
    run.push(direction_phase(Phase::Up, &run.up), on);
    if let Some(at) = up_failed {
        let headline = failed_at(Direction::Up, at, &run.up);
        return run.finish(started, check, headline);
    }

    // After up.
    on(Event::Phase {
        phase: Phase::AfterUp,
    });
    let at = Instant::now();
    let target_options = SchemaOptions {
        reordered: check.up.reordered.clone(),
        policies_public: options.policies_public,
    };
    let schema = checks::check_schema(
        session,
        &check.target,
        &target_options,
        &options.target_label,
        limits,
    )
    .await;
    let after_up = {
        let cx = Context {
            tables: &tables,
            before: &before,
            up: &up_walk,
            effects: &located,
            changed: &coverage.changed,
            limits,
            schema: target_options,
        };
        checks::after_up(session, &cx, &check.target).await
    };
    let rows_status = after_up.counts.status.and(after_up.values.status);
    let status = schema.status.and(rows_status).and(coverage.check.status);
    run.push(
        PhaseReport {
            phase: Phase::AfterUp,
            status,
            duration_ms: millis(at),
            summary: match (status, rows_status) {
                (Status::Failed, _) => "Not what the up migration should leave.".to_owned(),
                (Status::NeedsAcknowledgement, _) => {
                    "Data changed that the migration does not declare.".to_owned()
                }
                (Status::Warning, Status::Warning) => {
                    "As expected, with data loss its statements declare (or values not verifiable)."
                        .to_owned()
                }
                (Status::Warning, _) => {
                    "As expected; some tables it touches were empty.".to_owned()
                }
                _ => "Schema, row counts and values as expected.".to_owned(),
            },
            checks: vec![schema, coverage.check, after_up.counts, after_up.values],
        },
        on,
    );

    // Down.
    let Some(down) = &check.down else {
        run.losses = after_up.losses;
        let headline = run.headline(check);
        return run.finish(started, check, headline);
    };
    let (_, down_effects) = effects::walk(
        up_walk.clone(),
        down.statements.iter().map(|s| s.sql.as_str()),
    );
    located.extend(Located::all(
        Direction::Down,
        &down.statements,
        down_effects,
    ));
    on(Event::Phase { phase: Phase::Down });
    let ran = statements::run(session, &down.statements, limits, &mut |p| {
        on(progress(Direction::Down, p));
    })
    .await;
    run.down_status = DownStatus::Ran;
    let down_failed = ran.failed_at;
    run.push(direction_phase(Phase::Down, &ran), on);
    run.down = Some(ran);
    if let Some(at) = down_failed {
        // What the up migration lost stays the finding: the down did not
        // get to give anything back.
        run.losses = after_up.losses;
        let report = run.down.clone().unwrap_or_default();
        return run.finish(started, check, failed_at(Direction::Down, at, &report));
    }

    // After down.
    on(Event::Phase {
        phase: Phase::AfterDown,
    });
    let at = Instant::now();
    let base_options = SchemaOptions {
        reordered: down.reordered.clone(),
        policies_public: options.policies_public,
    };
    let schema = checks::check_schema(
        session,
        &check.base,
        &base_options,
        &options.base_label,
        limits,
    )
    .await;
    let after_down = {
        let cx = Context {
            tables: &tables,
            before: &before,
            up: &up_walk,
            effects: &located,
            changed: &coverage.changed,
            limits,
            schema: base_options,
        };
        checks::after_down(session, &cx).await
    };
    let sequences = checks::sequences_after_down(session, &before.sequences, limits).await;
    let status = schema
        .status
        .and(after_down.counts.status)
        .and(after_down.values.status)
        .and(sequences.status);
    run.losses = after_down.losses;
    run.push(
        PhaseReport {
            phase: Phase::AfterDown,
            status,
            duration_ms: millis(at),
            summary: match status {
                Status::Failed => "Not back as it was.".to_owned(),
                Status::NeedsAcknowledgement => {
                    "Not back as it was, where the migration does not declare it.".to_owned()
                }
                Status::Warning => {
                    "Back as it was, except data loss its statements declare.".to_owned()
                }
                _ => "Back as it was, every sampled value included.".to_owned(),
            },
            checks: vec![schema, after_down.counts, after_down.values, sequences],
        },
        on,
    );
    let headline = run.headline(check);
    run.finish(started, check, headline)
}

fn progress(direction: Direction, progress: Progress) -> Event {
    match progress {
        Progress::Running { index, total } => Event::Running {
            direction,
            index,
            total,
        },
        Progress::Done(result) => Event::Statement { direction, result },
    }
}

fn direction_phase(phase: Phase, report: &MigrationReport) -> PhaseReport {
    let ran = report
        .statements
        .iter()
        .filter(|s| s.status == StatementStatus::Passed)
        .count();
    PhaseReport {
        phase,
        status: if report.passed {
            Status::Passed
        } else {
            Status::Failed
        },
        duration_ms: report.duration_ms,
        summary: match report.failed_at {
            None => format!(
                "{} ran.",
                match ran {
                    1 => "1 statement".to_owned(),
                    n => format!("{n} statements"),
                }
            ),
            Some(at) => format!(
                "Statement {} of {} failed.",
                at + 1,
                report.statements.len()
            ),
        },
        checks: Vec::new(),
    }
}

fn failed_at(direction: Direction, at: usize, report: &MigrationReport) -> String {
    let error = report
        .statements
        .get(at)
        .and_then(|s| s.error.as_ref())
        .map(|e| format!(": {}", e.message))
        .unwrap_or_default();
    format!(
        "Failed at statement {} of {} of the {} migration{error}",
        at + 1,
        report.statements.len(),
        direction.word()
    )
}

/// The tables the up migration touches, which were empty, and the check
/// saying so.
struct Coverage {
    check: CheckReport,
    nothing_checked: bool,
    empty: Vec<String>,
    /// The base tables (`schema`, `name`) something rows matter to touches
    /// ([`effects::Effect::needs_rows`]): what it changes.
    changed: Vec<(String, String)>,
}

/// What the up migration touches (any table it alters, renames, drops,
/// changes rows of; every table for a `DO` block), which of those held no
/// rows to check on, and whether that leaves nothing checked: only when
/// every table touched by something rows matter to (data changed, a
/// constraint validated…) was empty. A migration of renames, nullable
/// columns and plain indexes needs no rows.
fn coverage(
    tables: &[snapshot::TableInfo],
    before: &snapshot::Snapshot,
    walk: &Walk,
    effects: &[Located],
) -> Coverage {
    use effects::Effect;
    let mut touched: Vec<(usize, bool)> = Vec::new();
    for located in effects {
        let rows = located.effect.needs_rows();
        match &located.effect {
            Effect::TableDropped { table }
            | Effect::TableRenamed { table }
            | Effect::ColumnAdded { table, .. }
            | Effect::ColumnDropped { table, .. }
            | Effect::ColumnRenamed { table, .. }
            | Effect::ColumnConverted { table, .. }
            | Effect::RowsDeleted { table, .. }
            | Effect::RowsAdded { table }
            | Effect::ValuesChanged { table, .. }
            | Effect::Altered { table, .. } => touched.push((*table, rows)),
            Effect::LabelRenamed { enum_type, .. } => {
                touched.extend(
                    (0..walk.tables.len())
                        .filter(|&t| {
                            walk.tables[t]
                                .columns
                                .iter()
                                .any(|c| c.types.contains(enum_type))
                        })
                        .map(|t| (t, rows)),
                );
            }
            Effect::Detached { parent, child } | Effect::Attached { parent, child } => {
                touched.extend([(*parent, rows), (*child, rows)]);
            }
            Effect::Opaque => touched.extend((0..walk.tables.len()).map(|t| (t, rows))),
            Effect::TableCreated { .. } => {}
        }
    }
    let is = |info: &snapshot::TableInfo, t: usize| {
        walk.tables[t]
            .base
            .as_ref()
            .is_some_and(|(s, n)| *s == info.schema && *n == info.name)
    };
    let bases: Vec<&snapshot::TableInfo> = tables
        .iter()
        .filter(|info| touched.iter().any(|&(t, _)| is(info, t)))
        .collect();
    let changed: Vec<&snapshot::TableInfo> = bases
        .iter()
        .copied()
        .filter(|info| touched.iter().any(|&(t, rows)| rows && is(info, t)))
        .collect();
    let held_none = |info: &snapshot::TableInfo| {
        before
            .counts
            .get(&(info.schema.clone(), info.name.clone()))
            .is_some_and(|n| *n == 0)
    };
    let empty: Vec<String> = bases
        .iter()
        .filter(|info| held_none(info))
        .map(|info| info.label())
        .collect();
    let nothing_checked = !changed.is_empty() && changed.iter().all(|info| held_none(info));
    let check = CheckReport {
        kind: CheckKind::Coverage,
        status: if empty.is_empty() {
            Status::Passed
        } else {
            Status::Warning
        },
        summary: if bases.is_empty() {
            "It touches no table holding rows: what it creates is checked by the schema.".to_owned()
        } else if nothing_checked {
            "Nothing to check on: every table it changes is empty.".to_owned()
        } else if empty.is_empty() {
            format!("Every table it touches held rows ({}).", bases.len())
        } else if changed.is_empty() {
            format!(
                "{} of the {} tables it touches were empty; nothing it does depends on rows (renames, nullable columns, plain indexes…).",
                empty.len(),
                bases.len()
            )
        } else {
            format!(
                "{} of the {} tables it touches were empty: nothing of them was checked on rows.",
                empty.len(),
                bases.len()
            )
        },
        details: empty.iter().take(50).cloned().collect(),
        tables: Vec::new(),
    };
    Coverage {
        check,
        nothing_checked,
        empty,
        changed: changed
            .iter()
            .map(|info| (info.schema.clone(), info.name.clone()))
            .collect(),
    }
}

/// The verdict of a run's phases, data loss and down migration: failed when
/// anything failed, else needs acknowledgement when anything does (an
/// up-only run too: acknowledged, it is passed up only), else passed up
/// only without a down migration, else passed.
pub fn verdict(phases: &[PhaseReport], losses: &[DataLoss], down: DownStatus) -> Verdict {
    let any = |status: Status| {
        phases.iter().any(|p| p.status == status) || losses.iter().any(|l| l.status == status)
    };
    if any(Status::Failed) {
        Verdict::Failed
    } else if any(Status::NeedsAcknowledgement) {
        Verdict::NeedsAcknowledgement
    } else if down == DownStatus::NotProvided {
        Verdict::PassedUpOnly
    } else {
        Verdict::Passed
    }
}

/// A report in the making.
struct Run {
    phases: Vec<PhaseReport>,
    data: DataSource,
    up: MigrationReport,
    down: Option<MigrationReport>,
    down_status: DownStatus,
    losses: Vec<DataLoss>,
    tables: usize,
    rows: i64,
    nothing_checked: bool,
    empty_tables: Vec<String>,
    policies_public: bool,
}

impl Run {
    fn push(&mut self, phase: PhaseReport, on: &mut (dyn FnMut(Event) + Send)) {
        on(Event::PhaseDone {
            phase: Box::new(phase.clone()),
        });
        self.phases.push(phase);
    }

    fn headline(&self, check: &Check) -> String {
        let failed = self.phases.iter().find(|p| p.status == Status::Failed);
        if let Some(phase) = failed {
            let what = phase
                .checks
                .iter()
                .find(|c| c.status == Status::Failed)
                .map_or_else(|| phase.summary.clone(), |c| c.summary.clone());
            let when = match phase.phase {
                Phase::AfterUp => "after the up migration",
                Phase::AfterDown => "after the down migration",
                _ => "before the migration",
            };
            return format!("Failed {when}: {what}");
        }
        let rows = checks::thousands(self.rows);
        let ran = if check.down.is_some() {
            format!("Up and down ran on {rows} rows.")
        } else {
            format!("Up ran on {rows} rows.")
        };
        let no_down = if check.down.is_some() {
            ""
        } else {
            " No down migration."
        };
        let places = |n: usize| {
            if n == 1 {
                "1 place".to_owned()
            } else {
                format!("{n} places")
            }
        };
        let pending = self
            .losses
            .iter()
            .filter(|l| l.status == Status::NeedsAcknowledgement)
            .count();
        let unverified = self
            .phases
            .iter()
            .any(|p| p.status == Status::NeedsAcknowledgement);
        if pending > 0 {
            return format!(
                "{ran} Data changed in {} the migration does not declare: acknowledge it, or change the migration.{no_down}",
                places(pending)
            );
        }
        if unverified {
            return format!(
                "{ran} Some of what it changes could not be verified: read the report, then acknowledge it or change the migration.{no_down}"
            );
        }
        if self.nothing_checked {
            return format!(
                "{ran} Every table it changes is empty: nothing was checked on rows.{no_down}"
            );
        }
        let lost: Vec<&DataLoss> = self.losses.iter().filter(|l| l.expected).collect();
        let as_flagged = lost
            .iter()
            .all(|l| l.cause.as_ref().is_some_and(|c| c.flag == Flag::Flagged));
        match (check.down.is_some(), lost.len()) {
            (true, 0) => format!("{ran} Everything came back."),
            (false, 0) => format!("Up ran on {rows} rows and kept them. No down migration."),
            (_, n) => format!(
                "{ran} Data is lost in {}, as {}.{no_down}",
                places(n),
                if as_flagged {
                    "flagged"
                } else {
                    "its statements say"
                }
            ),
        }
    }

    fn finish(self, started: Instant, check: &Check, headline: String) -> Report {
        let mut not_compared = vec![
            "grants and owners".to_owned(),
            "whether materialized views hold rows".to_owned(),
            "triggers' and functions' bodies".to_owned(),
        ];
        if self.policies_public {
            not_compared.push("the roles policies apply to (PUBLIC here)".to_owned());
        }
        Report {
            verdict: verdict(&self.phases, &self.losses, self.down_status),
            headline,
            data: self.data,
            sample: check.options.sample,
            tables: self.tables,
            rows: self.rows,
            phases: self.phases,
            up: self.up,
            down_status: self.down_status,
            down: self.down,
            data_loss: self.losses,
            nothing_checked: self.nothing_checked,
            empty_tables: self.empty_tables,
            not_compared,
            locks_from: "pg_locks, read before each statement's COMMIT (exact); documented for statements outside a transaction (CONCURRENTLY)".to_owned(),
            duration_ms: millis(started),
        }
    }
}
